//         if (this ->At(i) == myObject) ...//      };//   };//// Note that the iterator instance and for loop are enclosed within their own block. This// technique is required only if two or more iterators could share the same scope, in which// case the wrong failure handler could be invoked if the scope is not explicitly constrained.//// When you create a subclass of CArrayIterator, you typically add new methods that return the// location of the first, current, and next entities in the array. You also override the Reset// method if you change the bounds of the iteration during the lifetime of the iterator object.{public:	CArrayIterator_AC(const CDynamicArray_AC* itsDynamicArray,				   ArrayIndex_AC itsLowBound, ArrayIndex_AC itsHighBound,				   bool itsForward = kIterateForward_AC);	CArrayIterator_AC(const CDynamicArray_AC* itsDynamicArray, bool itsForward = kIterateForward_AC);	// Iterate over the entire available array. kMaxLong is ok here it will get bounded in CommonInit	~CArrayIterator_AC();	// Remove me from the linked list of iterators		//	// Required functions 	//	ArrayIndex_AC First();	inline ArrayIndex_AC Current() const { return fCurrentIndex; }	ArrayIndex_AC Next();	//	// Convenience functions for C++meisters	////••• Interferes with other coercion!!	inline operator ArrayIndex_AC() const { return Current(); }	inline ArrayIndex_AC operator++() { return Next(); }	inline ArrayIndex_AC operator++(int) { ArrayIndex_AC returnVal = Current(); Next(); return returnVal; }	//	// Compatibility functions	//	inline ArrayIndex_AC FirstIndex() { return First(); }	inline ArrayIndex_AC CurrentIndex() const { return Current(); }	inline ArrayIndex_AC NextIndex() { return Next(); }		//	// Helper functions	//	void Deleted(ArrayIndex_AC theIndex, ArrayIndex_AC theCount);		// Bends the index in the Iteration node to account for the deleted elements	void Inserted(ArrayIndex_AC theIndex, ArrayIndex_AC theCount);		// Bends the index to account for the inserted elements 	void AbortIteration();		// Called when iterations are in progress and the CDynamicArray_AC is deleted	inline CArrayIterator_AC* NextLink() const { return fNextLink; }		// Get the next iterator in the chain. 	inline void SetNextLink(CArrayIterator_AC* iterator) { fNextLink = iterator; }		// Set the next iterator in the chain. protected:	void CommonInit();		// Called by the constructors to do common initialization and reset the iteration	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------public:	// These items are currently public for searching	ArrayIndex_AC		fCurrentIndex;			// The current position in the array.	ArrayIndex_AC		fLowBound;				// The lowest position in the array that can												// be accessed during this iteration. The 												// lowest valid value is 1.	ArrayIndex_AC		fHighBound;				// The highest position in the array that												// can be accessed during this iteration.private:	CArrayIterator_AC*	fNextLink;				// Internal to MacApp - not documented.  Link												// to next iterator.	protected:	const CDynamicArray_AC* fDynamicArray;		// A protected field that points to an												// instance of a TDynamicArray or its subclass												// over whose elements the iteration occurs.	bool				fIterateForward;		// A protected field that indicates the direction												// of the interation. This field is set to true												// for forward iteration; false for backward iteration.};//========================================================================================// CommonArrayIterator_AC// Returns pointers TO array elements (not pointers stored IN array elements)// Returns NULL pointers for no element//========================================================================================class EXPORT_AC CCommonArrayIterator_AC : public CArrayIterator_AC{public:	CCommonArrayIterator_AC(const CDynamicArray_AC* inList,					ArrayIndex_AC inLowBound, ArrayIndex_AC inHighBound,					bool inForward = kIterateForward_AC);	CCommonArrayIterator_AC(const CDynamicArray_AC* inList, bool inForward = kIterateForward_AC);	//	// Required functions 	//	void* First();	inline void* Current() const { return fCurrentElement; }	void* Next();protected:	void* fCurrentElement;									// current object address of this iteration};//========================================================================================// CCommonVoidIterator_AC// Returns pointers stored IN elements (not pointers TO elements)// Returns NULL pointers for no element//========================================================================================class EXPORT_AC CCommonVoidIterator_AC : public CCommonArrayIterator_AC{public:	CCommonVoidIterator_AC(const CDynamicArray_AC* itsList,					ArrayIndex_AC itsLowBound, ArrayIndex_AC itsHighBound,					bool itsForward = kIterateForward_AC);	CCommonVoidIterator_AC(const CDynamicArray_AC* itsList, bool itsForward = kIterateForward_AC);	//	// Required functions 	//	void* First();	inline void* Current() const { return fCurrent; }	void* Next();protected:	void* fCurrent;									// current object of this iteration};//========================================================================================// TemplateArrayIterator_AC// Returns pointers TO items stored in elements// Returns NULL pointers for no element//========================================================================================template <class T>class TemplateArrayIterator_AC : public CCommonArrayIterator_AC{public:	TemplateArrayIterator_AC(const CDynamicArray_AC* inList,					ArrayIndex_AC inLowBound, ArrayIndex_AC inHighBound,					bool inForward = kIterateForward_AC)		:	CCommonArrayIterator_AC(inList, inLowBound, inHighBound, inForward)		{ }	TemplateArrayIterator_AC(const CDynamicArray_AC* inList,					bool inForward = kIterateForward_AC)		:	CCommonArrayIterator_AC(inList, inForward)		{ }	//	// Required functions 	//	inline T* First() { return reinterpret_cast<T*>(CCommonArrayIterator_AC::First()); }	inline T* Current() const { return reinterpret_cast<T*>(CCommonArrayIterator_AC::Current()); }	inline T* Next() { return reinterpret_cast<T*>(CCommonArrayIterator_AC::Next()); }	//	// Convenience functions for C++meisters	//	inline T* operator++() { return Next(); }	inline T* operator++(int) { T* returnVal = Current(); Next(); return returnVal; }	inline operator T*() const { return Current(); }	inline T* operator->() const { return Current(); } // this is only valid for non NULL	inline T& operator*() const { return *Current(); } // this is only valid for non NULL};//========================================================================================// TemplateScalarIterator_AC// Returns items stored IN elements that are the sizeof(void*) but the items are// scalars (they can't be dereferenced)//========================================================================================template <class T>class TemplateScalarIterator_AC : public CCommonVoidIterator_AC{public:	TemplateScalarIterator_AC(const CDynamicArray_AC* inList,					ArrayIndex_AC inLowBound, ArrayIndex_AC inHighBound,					bool inForward = kIterateForward_AC) :	CCommonVoidIterator_AC(inList, inLowBound, inHighBound, inForward)	{ }	TemplateScalarIterator_AC(const CDynamicArray_AC* inList, bool inForward = kIterateForward_AC) :	CCommonVoidIterator_AC(inList, inForward)	{ }	//	// Required functions 	//	inline T First() { return reinterpret_cast<T>(CCommonVoidIterator_AC::First()); }	inline T Current() const { return reinterpret_cast<T>(CCommonVoidIterator_AC::Current()); }	inline T Next() { return reinterpret_cast<T>(CCommonVoidIterator_AC::Next()); }	//	// Convenience functions for C++meisters	//	inline T operator++() { return Next(); }	inline T operator++(int) { T returnVal = Current(); Next(); return returnVal; }	inline operator T() const { return Current(); }};//========================================================================================// TemplateIterator_AC// Returns items stored IN elements that are the sizeof(void*) and are pointers// of some kind//========================================================================================// •••  Was: !qMSWindows#if !_MSC_VER	template <class T>	class EXPORT_AC TemplateIterator_AC : public TemplateScalarIterator_AC<T>	{	public:		TemplateIterator_AC(const CDynamicArray_AC* inList,						ArrayIndex_AC inLowBound, ArrayIndex_AC inHighBound,						bool inForward = kIterateForward_AC) :		TemplateScalarIterator_AC<T>(inList, inLowBound, inHighBound, inForward)		{ }			TemplateIterator_AC(const CDynamicArray_AC* inList, bool inForward = kIterateForward_AC) :		TemplateScalarIterator_AC<T>(inList, inForward)		{ }			inline T operator->() const { return Current(); }	};	#else	template <class T>	class TemplateIterator_AC : public CCommonVoidIterator_AC	{	public:		TemplateIterator_AC(const CDynamicArray_AC* inList,						ArrayIndex_AC inLowBound, ArrayIndex_AC inHighBound,						bool inForward = kIterateForward_AC)			:	CCommonVoidIterator_AC(inList, inLowBound, inHighBound, inForward)			{ }			TemplateIterator_AC(const CDynamicArray_AC* inList, bool inForward = kIterateForward_AC)			:	CCommonVoidIterator_AC(inList, inForward)			{ }			//		// Required functions 		//		inline T First() { return reinterpret_cast<T>(CCommonVoidIterator_AC::First()); }		inline T Current() const { return reinterpret_cast<T>(CCommonVoidIterator_AC::Current()); }		inline T Next() { return reinterpret_cast<T>(CCommonVoidIterator_AC::Next()); }			//		// Convenience functions for C++meisters		//		inline T operator++() { return Next(); }		inline T operator++(int) { T returnVal = Current(); Next(); return returnVal; }		inline operator T() const { return Current(); }		inline T operator->() const { return Current(); }	};	#endif// A couple of convenience exports.EXPORT_CLASS_AC(TemplateScalarIterator_AC<Handle>)EXPORT_CLASS_AC(TemplateScalarIterator_AC<long>)/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/12/96	Started the release process, removing triple-•, initials,							inappropriate comments.		04/23/96	Use CTempObject/Handle/Region/Ptr, etc.		04/23/96	Eliminated custom embedded FailInfo handling, derive from MDestructo		04/23/96	Update iterators to be OD stylish.							Split MDestructo out as a separate class		04/20/96	Remove implementation of CArrayIterator_AC::operator new		04/18/96	Use post-increment with iterators in while loops		04/15/96	Added CArrayIterator_AC::AbortIteration() which is called when the CDynamicArray_AC is deleted							during iteration. Removed CArrayIterator_AC::fPreviousLink since the links are only used as single links.							Added Anotherxxx to the iterators. It returns the index and then advances the iteration		----- R10 -----		03/31/96	Removed UList from includes again. Use a double coercionto make SCpp shutup instead.		03/30/96	Move trivial (restacking of parameters) constructors to inline							Added include for UList to make SCpp shut up about casting incomplete structure types		 3/04/96	Removed inlining for CArrayIterator_AC::FirstIndex/NextIndex to		 					reduce code bulk.		 3/01/96	Re-arranged data members of CArrayIterator_AC, natural alignment results in 		 					reduced storage size. (reduced stack requirements)		----- 3.3b1 -----		  7/5/95	Cosmetic. 		 5/26/94	Add cleanup proc. */#endif // __CListIterator_AC__